<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Str;class Request extends Model{public $incrementing=false;protected $keyType='string';protected $fillable=['user_id','service_id','provider_id','name','phone','email','message','status'];protected static function booted(){static::creating(fn($m)=>$m->id??=(string)Str::uuid());}public function user(){return $this->belongsTo(User::class);}public function service(){return $this->belongsTo(Service::class);}public function provider(){return $this->belongsTo(Provider::class);}public function assignments(){return $this->hasMany(RequestAssignment::class);}}
